"""Исходник документации ITRUPANEL: русский и английский тексты рядом.
Запуск: python3 release/docs-src.py -> release/docs-content.json (дальше i18n/docs.mjs собирает docs.html и en/docs.html).

ПРАВИЛО: каждое нововведение (новый пункт меню, новая функция, изменение работы раздела) обязательно описывается здесь,
в русском и английском тексте, В ТОМ ЖЕ выпуске. Сборка не пройдёт, если пункт меню панели не описан."""
import json, pathlib

